<?php
namespace App\Services\Football\Tickets;use App\Models\Ticket;final class TicketRiskService{public function recalculate(Ticket $ticket):Ticket{$ticket->loadMissing('selections');$odds=$ticket->selections->pluck('manual_odds')->filter(fn($v)=>$v!==null&&$v>=1.01);$combined=$odds->count()===$ticket->selections->count()&&$odds->isNotEmpty()?$odds->reduce(fn($c,$o)=>$c*(float)$o,1.0):null;$ticket->combined_odds=$combined?round($combined,3):null;$ticket->potential_return=($combined&&$ticket->stake_amount)?round($combined*(float)$ticket->stake_amount,2):null;$ticket->save();return$ticket;}public function guardrails(Ticket $ticket):array{$w=[];if($ticket->bankroll&&$ticket->stake_amount&&((float)$ticket->stake_amount/(float)$ticket->bankroll)*100>2)$w[]='Stake exceeds 2% of recorded bankroll while the model is being validated.';if($ticket->selections()->count()>6)$w[]='More than six legs materially increases accumulator failure risk.';return$w;}}
